import * as THREE from 'three/webgpu';
import { texture, MeshBasicNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture from imageUrl
  const textureAsset = ctx.textureLoader.load(config.imageUrl);

  // Create plane geometry with correct aspect ratio (512:320 = 1.6:1)
  const planeGeometry = new THREE.PlaneGeometry(512 / 320, 1);

  // Create TSL-based material with texture
  const textureNode = texture(textureAsset);
  const planeMaterial = new MeshBasicNodeMaterial({
    colorNode: textureNode,
    transparent: true
  });

  // Create and add plane mesh
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Render text content via fontAtlas
  if (config.textContent && ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createMesh(config.textContent, {
      font: 'Lora',
      fontSize: 0.34,
      fontWeight: 400,
      color: config.colors?.ink || '#16161d',
      align: 'center',
      anchorX: 'center',
      anchorY: 'middle'
    });

    if (textMesh) {
      textMesh.position.z = 0.1;
      group.add(textMesh);
    }
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
        ctx.primitives[prim.name](group, prim.params || {});
      }
    }
  }

  // Apply scene transforms
  if (config.scenePosition) {
    group.position.set(...config.scenePosition);
  }
  if (config.sceneRotation) {
    group.rotation.set(...config.sceneRotation);
  }
  if (config.sceneScale) {
    group.scale.set(...config.sceneScale);
  }

  // Setup cleanup function
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    textureAsset.dispose();
    gsap.killTweensOf(group);
  };

  // Setup event handlers
  group.userData.handlers = {};

  return group;
}
